function uniqueLast(rows) {
  const map = new Map();
  rows.forEach((row, index) => {
    map.set(row.id, { data: row, index });
  });

  return Array.from(map.values())
    .sort((a, b) => a.index - b.index)
    .map(item => item.data);
}

function uniqueLast(rows) {
    const map = new Map();
    for (let i = 0; i < rows.length; i++) {
        map.set(rows[i].id, rows[i]);
    }
    const result = [...map.values()];
    return result;
}
